{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "The closest analogue WAY100635 showed good maximal brain uptake (5.0% ID) in cynomolgus monkeys by PET, demonstrating adequate CNS access despite known P-gp liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "[3H]WAY100635 penetrated the BBB in mice, with 1.5-1.8% of injected radioactivity in whole brain at 5 min and receptor-specific distribution.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "[18F]FCWAY, a close fluorinated analogue, is BBB-permeable and used for 5-HT1A PET imaging in rodents and humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In humans, 18F-mefway, another close analogue, showed rapid brain uptake with a peak SUV of 1.7.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "The less similar para-fluorobenzoyl analogue MPPF is a P-gp substrate with low brain uptake (0.05% ID/g), showing that efflux can reduce exposure in this series; this is outweighed by the higher-similarity WAY100635 data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close WAY100635 analogue (norbornanecarbonyl replacing cyclohexanecarbonyl). WAY100635 and several close 5-HT1A radiotracers show adequate brain uptake in rodents, monkeys, and humans despite being P-gp substrates. The norbornane group is lipophilic and should preserve CNS access; therefore the molecule is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain uptake measurement for the exact norbornane analogue; extrapolation from WAY100635 and fluorinated analogues.",
    "Unbound brain-to-plasma ratio or human CSF data not available for the query.",
    "Quantitative contribution of P-gp/BCRP efflux to the query's net brain exposure is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

